insert into sts_extra_questions values
('gst','Which details should generally appear on a tax invoice as prescribed by GST rules?','["Supplier details, GSTIN, invoice number/date and applicable supply/tax details","Only the buyer name","Only a handwritten total","Only the bank account number"]',0,'A tax invoice must contain the particulars prescribed by the applicable GST rules.'),
('gst','What is the main purpose of matching purchase records with GSTR-2B?','["To reconcile eligible ITC and identify differences","To calculate employee leave","To issue driving licences","To file passport applications"]',0,'Reconciliation helps identify mismatches and review ITC eligibility.'),
('gst','What does HSN generally relate to?','["Classification of goods","Employee salary","Bank branch identification","Income tax refund status"]',0,'HSN is the Harmonized System of Nomenclature used for classifying goods.'),
('gst','What does SAC generally relate to under GST?','["Classification of services","Vehicle chassis number","PAN allotment","Bank cheque number"]',0,'SAC is the Services Accounting Code used for services.'),
('gst','What should a business do when GST registration details change?','["Apply for amendment as required under GST rules","Ignore the change permanently","Create a new PAN automatically","Delete all invoices"]',0,'Registration particulars should be amended through the prescribed process when required.'),
('gst','What is the general purpose of a GST credit note?','["Record a reduction in value or tax in eligible circumstances","Record employee attendance","Apply for a passport","Register a trademark"]',0,'A credit note may be used for permitted reductions in taxable value or tax.'),
('gst','What is the general purpose of a GST debit note?','["Record an increase in value or tax in eligible circumstances","Cancel an employee ID","Create a bank account","File Form 16"]',0,'A debit note may be used where taxable value or tax charged needs to increase.'),
('gst','Which factor is important when determining whether a supply is inter-state?','["Place of supply and location of supplier under applicable rules","Colour of invoice paper","Number of employees only","Bank name"]',0,'The place-of-supply and supplier-location rules determine the nature of supply.'),
('gst','What is a composite supply generally taxed according to?','["The principal supply, subject to GST law","The lowest-valued item in every case","The customer’s bank","The invoice font"]',0,'A composite supply is generally treated as the principal supply for rate purposes.'),
('gst','What is a mixed supply generally treated as for rate purposes?','["The item attracting the highest applicable rate, subject to law","Always exempt","Always zero-rated","A salary payment"]',0,'A mixed supply is generally taxed at the highest rate applicable to its constituent supplies.'),
('gst','Can GST registration threshold rules be identical for every state and every business type?','["No; applicable thresholds and exceptions must be checked","Yes, without exception","Only the invoice value matters","Thresholds are set by each customer"]',0,'Thresholds and exceptions depend on the law, state and nature of activity.'),
('gst','What is the purpose of an annual return under GST where applicable?','["Summarise relevant annual GST information","Replace all sales invoices","Register a vehicle","Create a PAN"]',0,'An annual return consolidates specified information for the financial year, where required.'),
('gst','Why should a taxpayer review the GST portal notices section?','["To identify communications, notices and response deadlines","To view weather forecasts","To check driving test results","To download passport stamps"]',0,'Portal communications may carry statutory response deadlines.'),
('gst','What should be done before claiming ITC on an invoice?','["Check eligibility, receipt of supply, tax-document requirements and restrictions","Claim every invoice automatically","Ignore blocked-credit rules","Delete the supplier record"]',0,'ITC claims require compliance with statutory conditions and restrictions.'),
('gst','Which transaction may require special review for reverse charge?','["A notified category of supply covered by reverse-charge provisions","Every salary payment","Every personal grocery purchase","Every bank deposit"]',0,'Reverse charge applies only to specified categories and circumstances under law.'),
('gst','What is the purpose of an e-invoice IRN where e-invoicing applies?','["A unique Invoice Reference Number generated through the notified system","A vehicle registration number","An employee payroll code","A bank IFSC"]',0,'The IRN uniquely identifies an e-invoice under the applicable e-invoicing system.'),
('gst','What should be checked before issuing an e-way bill?','["Applicability, consignment details and required transport information","Only the customer’s email colour","Only the driver’s birthday","Nothing at all"]',0,'E-way bill requirements depend on the movement, value and applicable rules.'),
('gst','What is the role of a GST practitioner or tax professional?','["Assist with permitted compliance work while the taxpayer remains responsible as prescribed","Guarantee every refund","Change the law","Automatically waive tax"]',0,'Professionals can assist with permitted compliance, but legal responsibilities remain as prescribed.'),
('gst','What should a taxpayer do if a supplier invoice is missing from the relevant statement?','["Contact the supplier and reconcile before deciding ITC treatment","Assume ITC is always allowed","Delete the purchase from books without review","Claim a refund automatically"]',0,'Investigate mismatches and apply current ITC rules before claiming credit.'),
('gst','Why is accurate HSN/SAC classification important?','["It helps determine correct reporting and applicable tax treatment","It replaces GST registration","It guarantees a refund","It sets employee wages"]',0,'Correct classification supports accurate invoicing, reporting and tax treatment.'),
('gst','What does GSTIN generally contain?','["15-character identification number","A 5-digit vehicle number","A 12-digit bank account password","A 2-character state name only"]',0,'GSTIN is a 15-character identification number with prescribed components.'),
('gst','Is an exempt supply always the same as a zero-rated supply?','["No, they are distinct concepts under GST law","Yes, always identical","Both mean no records are needed","Both are income tax forms"]',0,'Exempt and zero-rated supplies have different legal treatment and consequences.'),
('gst','What is the purpose of keeping purchase and sales registers?','["Maintain records and support reconciliations and returns","Replace all statutory returns","Avoid all audits automatically","Create a TAN"]',0,'Books and registers support accurate returns, reconciliations and compliance.'),
('gst','What should a business do if tax was paid under the wrong head?','["Review the applicable correction/refund process under law","Ignore it forever","Create another GSTIN immediately","Change the invoice date without evidence"]',0,'Use the correction or refund process provided by applicable law; facts matter.'),
('gst','When should a GST return generally be filed?','["By the applicable due date, subject to the taxpayer’s category and notifications","Whenever convenient without consequences","Only after five years","Only when a customer asks"]',0,'Due dates depend on the return, taxpayer category and applicable notifications.'),
('gst','What is the purpose of reconciling e-invoice data with books?','["Identify missing, duplicated or inconsistent invoice records","Calculate school grades","Register a company director","Check vehicle fuel efficiency"]',0,'Reconciliation helps ensure books and portal records are consistent.'),
('gst','Can a tax invoice be altered informally after issue without following applicable rules?','["No; corrections should follow the prescribed legal process","Yes, always erase the original","Only by changing the PDF locally","Only by changing the customer name silently"]',0,'Invoice corrections should follow applicable GST requirements and preserve proper records.'),
('gst','What should be reviewed before filing GSTR-3B?','["Outward liability, eligible ITC, reversals and tax payment details","Only office attendance","Only bank passbook cover","Only the logo"]',0,'Review relevant liability and ITC records before filing the summary return.'),
('gst','What is a GST challan generally used for?','["Pay tax or other amounts through the prescribed portal process","Issue a PAN","Record exam answers","Create an e-way bill in every case"]',0,'A challan is used for payments through the prescribed GST payment process.'),
('gst','Why should businesses retain GST invoices and records?','["For compliance, reconciliation, audit and evidence","Only for decoration","To avoid registering books","To replace the GST portal"]',0,'Maintaining required records supports statutory compliance and verification.');
insert into sts_extra_questions values
('income-tax','What is an assessment year in the Indian income-tax system?','["The year following the financial year in which income is assessed","Always the same as calendar year","A GST return period","A bank accounting code"]',0,'The assessment year generally follows the financial year to which income relates.'),
('income-tax','What does ITR acknowledgement generally confirm?','["Receipt of return filing details by the portal","Automatic approval of every claim","Guaranteed refund payment","GST registration"]',0,'An acknowledgement records filing details; it does not itself guarantee acceptance of claims or a refund.'),
('income-tax','What is a revised return used for, where permitted?','["Correcting an earlier filed return under applicable law","Registering a vehicle","Creating a GSTIN","Changing a bank IFSC"]',0,'A revised return can correct an earlier return within the statutory conditions and time limits.'),
('income-tax','What is a belated return?','["A return filed after the original due date, subject to law","A return filed before the financial year","A GST invoice","A tax refund order"]',0,'A belated return is filed after the original due date within the permitted statutory period.'),
('income-tax','What is the purpose of checking the applicable tax regime before filing?','["Rates, deductions and eligibility can differ by regime and year","It changes the PAN number","It guarantees zero tax","It replaces ITR verification"]',0,'Tax regime choice affects applicable rates and deduction eligibility, subject to law.'),
('income-tax','What is a TDS certificate commonly used for?','["Evidence of tax deducted and deposited details","A GST registration application","A vehicle fitness certificate","A bank loan sanction"]',0,'TDS certificates provide details of tax deducted and related particulars.'),
('income-tax','What is the purpose of a challan counterfoil or payment receipt?','["Evidence of a tax payment transaction","Proof of GST exemption in all cases","A substitute for PAN","A salary slip"]',0,'Keep payment evidence and reconcile it with tax records and the portal.'),
('income-tax','What is the general purpose of a tax audit under income-tax law where applicable?','["Examine prescribed accounts and report specified particulars","Guarantee no tax is payable","Register a trademark","Approve a bank loan"]',0,'A tax audit examines prescribed accounts and reports particulars under the applicable provisions.'),
('income-tax','What is the purpose of documenting business expenses?','["Support accounting and any eligible deduction or expense claim","Automatically create a refund","Replace all invoices","Avoid keeping books"]',0,'Proper records help support expense treatment and compliance.'),
('income-tax','What should be done when TDS credit shown in records differs from the taxpayer’s records?','["Reconcile statements and contact the deductor or follow the portal process","Claim the difference without review","Ignore the mismatch permanently","Delete PAN"]',0,'Reconciliation can identify reporting or data-entry issues that need correction.'),
('income-tax','What is a notice response deadline?','["The date by which the requested response must be submitted, as specified","An optional date that can always be ignored","A GST due date in every case","A bank holiday list"]',0,'Read the notice carefully and respond within the stated statutory or portal deadline.'),
('income-tax','What should be checked before paying self-assessment tax?','["Computed tax liability, prepaid tax credits and applicable interest/fees","Only the colour of the payment screen","Only the bank branch address","Nothing"]',0,'Reconcile total tax liability with TDS/TCS, advance tax and other eligible credits.'),
('income-tax','What is the usual purpose of advance tax interest provisions?','["Address shortfall or delay in advance-tax payments where applicable","Provide a bonus refund","Register a company","Calculate GST turnover"]',0,'Interest may apply when statutory advance-tax payment conditions are not met.'),
('income-tax','What does TCS stand for in tax collection provisions?','["Tax Collected at Source","Total Cash Statement","Tax Credit Slip","Trade Collection Schedule"]',0,'TCS means Tax Collected at Source.'),
('income-tax','Why should taxpayers keep bank interest certificates and relevant statements?','["To report and reconcile taxable income where applicable","To replace PAN","To avoid reporting interest in all cases","To create a GST invoice"]',0,'Interest records help identify and report relevant income accurately.'),
('income-tax','What is the purpose of a deduction under the income-tax law?','["Reduce taxable income or tax as specifically allowed by law","Automatically cancel all tax liability","Replace an ITR","Create a GST credit note"]',0,'Deductions are allowed only as provided by law and subject to eligibility.'),
('income-tax','Is income from every source necessarily reported in the same way?','["No; classification and reporting depend on the income and applicable rules","Yes, all income is salary","Only cash income matters","Only business income is ever reported"]',0,'Income classification and reporting depend on the nature of income and law.'),
('income-tax','What is the purpose of e-verification of an ITR?','["Complete verification through a permitted method","Guarantee a refund in one day","Register for GST","Issue a TAN"]',0,'A return generally needs verification through an accepted method within applicable timelines.'),
('income-tax','What should a taxpayer do after receiving a refund failure or refund-related message?','["Check official portal status and follow the stated correction steps","Share passwords with strangers","File a duplicate PAN","Ignore the message without checking authenticity"]',0,'Use the official portal and verify the message before taking action.'),
('income-tax','What is the purpose of Form 15G/15H where eligible?','["Request non-deduction of specified tax at source subject to conditions","File an annual GST return","Register a company","Pay advance tax"]',0,'These declarations are available only to eligible persons and payments under prescribed conditions.'),
('income-tax','What is the role of a Tax Deduction Account Number (TAN)?','["Identify deductors/collectors in specified TDS/TCS compliance","Identify a vehicle","Replace the employee PAN in every case","Generate an ITR automatically"]',0,'TAN is used for specified TDS/TCS compliance where required.'),
('income-tax','What should be checked before claiming home-loan interest or principal tax benefits?','["Applicable section, tax regime, property/use conditions and supporting documents","Only the bank logo","Only the loan account colour","Nothing at all"]',0,'Eligibility depends on the applicable provisions, tax regime and facts.'),
('income-tax','Can a taxpayer rely only on a pre-filled ITR without reviewing it?','["No; review and correct information before submission","Yes, it is always complete and correct","Only if filing on a phone","Only if there is no salary"]',0,'Pre-filled data should be reviewed against the taxpayer’s own records.'),
('income-tax','What is the purpose of an income-tax demand notice?','["Communicate an amount payable or other specified matter for review/action","Guarantee a refund","Register a GSTIN","Issue a vehicle number"]',0,'Read the demand details, assessment reference and available response options carefully.'),
('income-tax','What is a rectification request generally used for?','["Seeking correction of a mistake apparent from the record where legally available","Rewriting tax law","Changing PAN identity","Replacing all tax returns"]',0,'Rectification is limited to errors and conditions allowed under the relevant provisions.'),
('income-tax','What is the purpose of Form 16A?','["TDS certificate for specified non-salary payments","Salary annual certificate only","GST annual return","E-way bill"]',0,'Form 16A is a TDS certificate for specified non-salary payments.'),
('income-tax','Why is it important to use the correct assessment year when filing an ITR?','["The return and applicable rules relate to a particular income period","It changes the taxpayer name automatically","It guarantees a refund","It replaces the financial year"]',0,'The assessment year identifies the year for which the return is filed.'),
('income-tax','What is the purpose of maintaining investment proofs where a claim requires them?','["Support the claim and demonstrate eligibility when required","Automatically waive tax","Replace a bank account","Create a GSTIN"]',0,'Supporting records may be needed to substantiate claims and respond to verification.'),
('income-tax','What should be done before using a tax rate or deduction figure from an old article?','["Verify the applicable financial/assessment year and current law","Assume it never changes","Use the oldest figure available","Ignore the taxpayer category"]',0,'Rates, thresholds and eligibility can change; verify the applicable year and law.'),
('income-tax','What is the purpose of checking the official portal for return processing status?','["See processing updates, communications and any action required","Guarantee acceptance of all deductions","Change the PAN","Replace bank statements"]',0,'Official portal status is the appropriate place to review processing updates and actions.');
