-- Expand Smart Tax Solution question bank to 50 questions per course.
-- Run AFTER supabase/seed-question-bank.sql in Supabase SQL Editor.
-- Safe to re-run: existing question text is not duplicated.
begin;

create temporary table sts_extra_questions(
 course_slug text, question_text text, options jsonb, correct_option integer, explanation text
) on commit drop;



with inserted as (
 select c.id,s.question_text,s.options,s.explanation,true
 from sts_extra_questions s join public.courses c on c.slug=s.course_slug
 where not exists(select 1 from public.questions q where q.course_id=c.id and q.question_text=s.question_text)
 returning id,course_id,question_text
)
select i.id,s.correct_option from inserted i join sts_extra_questions s on s.question_text=i.question_text
on conflict(question_id) do nothing;

select q.id,s.correct_option from sts_extra_questions s join public.courses c on c.slug=s.course_slug
join public.questions q on q.course_id=c.id and q.question_text=s.question_text
on conflict(question_id) do nothing;

commit;
